window.Icons = Icons;

window.getIcon = function(name, size = 32) {
  const svg = Icons[name] || Icons['folder'];
  return `<div class="icon-svg-wrapper" style="width:${size}px; height:${size}px; display:inline-flex; align-items:center; justify-content:center;">${svg}</div>`;
};

window.webGif = function(name, scale = 1, title = '') {
  const svg = Icons['gif-' + name] || '';
  const size = svg.match(/viewBox="0 0 (\d+) (\d+)"/);
  const w = (size ? +size[1] : 16) * scale;
  const h = (size ? +size[2] : 16) * scale;
  const tip = title ? ` title="${title}"` : '';
  return `<span class="web-gif" style="width:${w}px;height:${h}px"${tip}>${svg}</span>`;
};
